document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("button.show-more").forEach(e=>{e.addEventListener("click",function(e){e.preventDefault(),e.stopImmediatePropagation(),e.target.parentNode.querySelector(".list-downloads").classList.add("open"),e.target.style.display="none"})}),document.querySelectorAll("a.link-downloads").forEach(e=>{e.addEventListener("click",function(e){e.preventDefault(),e.stopImmediatePropagation();let t=e.target.dataset.log;fetch(document.location.protocol+"//"+document.location.host+"/wp-json/"+wordKeeperApiPath+"log/download",{method:"POST",body:"log="+t,headers:{"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8","X-Wp-Nonce":wpApiSettings.nonce}}).then(function(e){200==e.status?e.blob().then(e=>{let o=window.URL.createObjectURL(e),n=document.createElement("a");n.href=o,n.download=t,document.body.appendChild(n),n.click(),n.remove(),URL.revokeObjectURL(o)}):wordkeeper.notice.fire("error",[{text:"A problem occurred.  Contact support.",action:""}])})})})});